#if IS_NET_8_0_OR_GREATER
namespace Epiforge.Extensions.Expressions.Observable;

/// <summary>
/// Performs the primitive conversions and operators of expression trees on boxed values, each written as the C# cast or operator which compiles to the same instruction the expression compiler emits, so that results, wrapping, overflow and division by zero agree with a compiled lambda
/// </summary>
static class ClosureOperations
{
    internal static Func<object?, object?, object?>? Binary(ExpressionType nodeType, TypeCode type) =>
        (nodeType, type) switch
        {
            (ExpressionType.Add, TypeCode.SByte) => static (l, r) => unchecked((sbyte)((sbyte)l! + (sbyte)r!)),
            (ExpressionType.Add, TypeCode.Byte) => static (l, r) => unchecked((byte)((byte)l! + (byte)r!)),
            (ExpressionType.Add, TypeCode.Int16) => static (l, r) => unchecked((short)((short)l! + (short)r!)),
            (ExpressionType.Add, TypeCode.UInt16) => static (l, r) => unchecked((ushort)((ushort)l! + (ushort)r!)),
            (ExpressionType.Add, TypeCode.Int32) => static (l, r) => unchecked((int)l! + (int)r!),
            (ExpressionType.Add, TypeCode.UInt32) => static (l, r) => unchecked((uint)l! + (uint)r!),
            (ExpressionType.Add, TypeCode.Int64) => static (l, r) => unchecked((long)l! + (long)r!),
            (ExpressionType.Add, TypeCode.UInt64) => static (l, r) => unchecked((ulong)l! + (ulong)r!),
            (ExpressionType.Add, TypeCode.Single) => static (l, r) => unchecked((float)l! + (float)r!),
            (ExpressionType.Add, TypeCode.Double) => static (l, r) => unchecked((double)l! + (double)r!),
            (ExpressionType.AddChecked, TypeCode.SByte) => static (l, r) => checked((sbyte)((sbyte)l! + (sbyte)r!)),
            (ExpressionType.AddChecked, TypeCode.Byte) => static (l, r) => checked((byte)((byte)l! + (byte)r!)),
