            (ExpressionType.AddChecked, TypeCode.UInt16) => static (l, r) => checked((ushort)((ushort)l! + (ushort)r!)),
            (ExpressionType.AddChecked, TypeCode.Int32) => static (l, r) => checked((int)l! + (int)r!),
            (ExpressionType.AddChecked, TypeCode.UInt32) => static (l, r) => checked((uint)l! + (uint)r!),
            (ExpressionType.AddChecked, TypeCode.Int64) => static (l, r) => checked((long)l! + (long)r!),
