            (ExpressionType.Subtract, TypeCode.UInt32) => static (l, r) => unchecked((uint)l! - (uint)r!),
            (ExpressionType.Subtract, TypeCode.Int64) => static (l, r) => unchecked((long)l! - (long)r!),
            (ExpressionType.Subtract, TypeCode.UInt64) => static (l, r) => unchecked((ulong)l! - (ulong)r!),
