    internal static Func<object?, object?>? Conversion(TypeCode from, TypeCode to, bool @checked) =>
        (from, to, @checked) switch
        {
            (TypeCode.SByte, TypeCode.SByte, false) => static value => unchecked((sbyte)(sbyte)value!),
            (TypeCode.SByte, TypeCode.SByte, true) => static value => checked((sbyte)(sbyte)value!),
            (TypeCode.SByte, TypeCode.Byte, false) => static value => unchecked((byte)(sbyte)value!),
            (TypeCode.SByte, TypeCode.Byte, true) => static value => checked((byte)(sbyte)value!),
            (TypeCode.SByte, TypeCode.Int16, false) => static value => unchecked((short)(sbyte)value!),
            (TypeCode.SByte, TypeCode.Int16, true) => static value => checked((short)(sbyte)value!),
            (TypeCode.SByte, TypeCode.UInt16, false) => static value => unchecked((ushort)(sbyte)value!),
            (TypeCode.SByte, TypeCode.UInt16, true) => static value => checked((ushort)(sbyte)value!),
            (TypeCode.SByte, TypeCode.Int32, false) => static value => unchecked((int)(sbyte)value!),
            (TypeCode.SByte, TypeCode.Int32, true) => static value => checked((int)(sbyte)value!),
            (TypeCode.SByte, TypeCode.UInt32, false) => static value => unchecked((uint)(sbyte)value!),
            (TypeCode.SByte, TypeCode.UInt32, true) => static value => checked((uint)(sbyte)value!),
            (TypeCode.SByte, TypeCode.Int64, false) => static value => unchecked((long)(sbyte)value!),
