    internal static Func<object?, object?>? Unary(ExpressionType nodeType, TypeCode type) =>
        (nodeType, type) switch
        {
            (ExpressionType.Negate, TypeCode.SByte) => static value => unchecked((sbyte)(-(sbyte)value!)),
            (ExpressionType.NegateChecked, TypeCode.SByte) => static value => checked((sbyte)(-(sbyte)value!)),
            (ExpressionType.Negate, TypeCode.Int16) => static value => unchecked((short)(-(short)value!)),
            (ExpressionType.NegateChecked, TypeCode.Int16) => static value => checked((short)(-(short)value!)),
            (ExpressionType.Negate, TypeCode.Int32) => static value => unchecked(-(int)value!),
            (ExpressionType.NegateChecked, TypeCode.Int32) => static value => checked(-(int)value!),
            (ExpressionType.Negate, TypeCode.Int64) => static value => unchecked(-(long)value!),
            (ExpressionType.NegateChecked, TypeCode.Int64) => static value => checked(-(long)value!),
            (ExpressionType.Negate, TypeCode.Single) => static value => unchecked(-(float)value!),
            (ExpressionType.NegateChecked, TypeCode.Single) => static value => checked(-(float)value!),
            (ExpressionType.Negate, TypeCode.Double) => static value => unchecked(-(double)value!),
            (ExpressionType.NegateChecked, TypeCode.Double) => static value => checked(-(double)value!),
            (ExpressionType.Not, TypeCode.SByte) => static value => (sbyte)(~(sbyte)value!),
            (ExpressionType.OnesComplement, TypeCode.SByte) => static value => (sbyte)(~(sbyte)value!),
            (ExpressionType.Not, TypeCode.Byte) => static value => (byte)(~(byte)value!),
            (ExpressionType.OnesComplement, TypeCode.Byte) => static value => (byte)(~(byte)value!),
            (ExpressionType.Not, TypeCode.Int16) => static value => (short)(~(short)value!),
            (ExpressionType.OnesComplement, TypeCode.Int16) => static value => (short)(~(short)value!),
            (ExpressionType.Not, TypeCode.UInt16) => static value => (ushort)(~(ushort)value!),
            (ExpressionType.OnesComplement, TypeCode.UInt16) => static value => (ushort)(~(ushort)value!),
            (ExpressionType.Not, TypeCode.Int32) => static value => ~(int)value!,
            (ExpressionType.OnesComplement, TypeCode.Int32) => static value => ~(int)value!,
            (ExpressionType.Not, TypeCode.UInt32) => static value => ~(uint)value!,
            (ExpressionType.OnesComplement, TypeCode.UInt32) => static value => ~(uint)value!,
            (ExpressionType.Not, TypeCode.Int64) => static value => ~(long)value!,
            (ExpressionType.OnesComplement, TypeCode.Int64) => static value => ~(long)value!,
            (ExpressionType.Not, TypeCode.UInt64) => static value => ~(ulong)value!,
            (ExpressionType.OnesComplement, TypeCode.UInt64) => static value => ~(ulong)value!,
            (ExpressionType.Not, TypeCode.Boolean) => static value => BooleanBoxes.Box(!(bool)value!),
            _ => null
        };
